package jp.tapmarker;
import java.util.*;
public class PhaseEngineTest {
 static int n=0;static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);n++;System.out.println("PASS "+label);}
 static PhaseEngine.Region region(String id){PhaseEngine.Region r=new PhaseEngine.Region();r.id=id;r.name=id;r.bounds=new float[]{0,0,.5f,.5f};return r;}
 static PhaseEngine.Phase phase(String id){PhaseEngine.Phase p=new PhaseEngine.Phase();p.id=id;p.name=id;return p;}
 static PhaseEngine.Watch watch(String id,String region,int priority){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=id;w.regionId=region;w.priority=priority;return w;}
 static Map<String,float[]> samples(float a,float b,float c){Map<String,float[]> m=new HashMap<>();m.put("A",new float[]{a,a});m.put("B",new float[]{b,b});m.put("C",new float[]{c,c});return m;}
 static void rejectPrompt(String text,String label){try{PhasePrompt.parse(text);throw new AssertionError(label);}catch(IllegalArgumentException e){check(true,label);}}
 public static void main(String[] args){PhaseEngine e=new PhaseEngine();e.regions.put("A",region("A"));e.regions.put("B",region("B"));e.regions.put("C",region("C"));PhaseEngine.Phase p=phase("作業"),q=phase("結果");PhaseEngine.Watch a=watch("a","A",20),b=watch("b","B",10),c=watch("c","C",1);p.watches.add(a);p.watches.add(b);q.watches.add(c);e.phases.put(p.id,p);e.phases.put(q.id,q);e.enter(p.id,0);check(e.activeRegions().size()==2,"only current-phase regions active");check(e.activeRegions().stream().noneMatch(r->r.id.equals("C")),"inactive-phase region excluded");e.observe(samples(0,0,0),0);check(e.poll()==null,"first frame only establishes change baselines");e.observe(samples(1,1,1),100);check(e.poll()==b,"simultaneous changes choose highest priority");e.finish(b,100);check(e.poll()==a,"other simultaneous event retained for sequential execution");e.enter(p.id,200);e.observe(samples(0,0,0),200);e.observe(samples(1,1,1),300);b.nextPhase=q.id;PhaseEngine.Watch chosen=e.poll();e.finish(chosen,300);check(e.current.equals(q.id),"declared next phase entered");check(e.poll()==null,"old-phase queued action canceled on transition");e.observe(samples(1,1,1),300);check(e.poll()==null,"new phase receives fresh baseline");e.observe(samples(1,1,0),400);check(e.poll()==c,"new phase reacts only to its region");e.enter(q.id,500);e.observe(samples(1,1,0),500);e.observe(samples(0,0,0),600);check(e.poll()==null,"changes outside active regions ignored");for(int i=0;i<2048;i++)e.regions.put("extra"+i,region("extra"+i));check(e.regions.size()==2051&&e.activeRegions().size()==1,"many registered regions with no fixed count limit");PhaseEngine.Watch timer=watch("timer","",1);timer.condition=PhaseEngine.TIMEOUT;timer.action=PhaseEngine.WAIT;timer.timeoutMs=1000;PhaseEngine.Phase time=phase("時間");time.watches.add(timer);e.phases.put(time.id,time);e.enter(time.id,10000);check(e.activeRegions().isEmpty(),"timeout-only phase needs no pixel sampling");e.observe(new HashMap<>(),10999);check(e.poll()==null,"timeout does not fire early");e.observe(new HashMap<>(),11000);check(e.poll()==timer,"timeout uses phase entry time");e.observe(new HashMap<>(),12000);check(e.poll()==null,"timeout fires once per phase entry");e.enter(time.id,20000);e.observe(new HashMap<>(),21000);check(e.poll()==timer,"reentered phase rearms timeout");PhaseEngine.Watch match=watch("match","A",1);match.condition=PhaseEngine.MATCH;match.reference=new float[]{.5f,.5f};PhaseEngine.Phase matched=phase("一致");matched.watches.add(match);e.phases.put(matched.id,matched);e.enter(matched.id,0);e.observe(samples(.5f,0,0),0);check(e.poll()==match,"taught regional state triggers match");e.observe(samples(.5f,0,0),1);check(e.poll()==null,"unchanged match is latched");e.observe(samples(0,0,0),2);e.observe(samples(.5f,0,0),3);check(e.poll()==match,"leaving and reentering matching state rearms");match.reference=null;check(!e.validate().isEmpty(),"unrecorded match blocks execution");match.reference=new float[]{.5f,.5f};match.nextPhase="missing";check(!e.validate().isEmpty(),"missing next phase rejected");match.nextPhase="";check(e.validate().isEmpty(),"valid multiphase configuration accepted");PhaseEngine other=new PhaseEngine();other.regions.put("A",region("A"));PhaseEngine.Phase op=phase("作業");op.watches.add(watch("oa","A",1));other.phases.put(op.id,op);other.enter(op.id,0);other.observe(samples(.5f,0,0),0);check(other.poll()==null,"another app engine has independent baselines");String prompt="フェーズ「操作中」の間だけ領域「通知」を監視。通知が変化したら連打を一時停止し、通知の中央を1回タップ。フェーズ「結果確認」へ移る。";PhasePrompt parsed=PhasePrompt.parse(prompt);check(parsed.phase.equals("操作中")&&parsed.region.equals("通知")&&parsed.next.equals("結果確認"),"named phase prompt maps exact user example");parsed=PhasePrompt.parse("フェーズ「P」の間だけ領域「R」を監視。監視領域が変わったら監視領域中央をタップ。優先順位2。待機500ms");check(parsed.priority==2&&parsed.waitMs==500,"named prompt priority and wait interpreted");rejectPrompt("フェーズ「P」の間だけ領域「R」を監視。別の領域が変化したら連打を一時停止し、Rの中央を1回タップ","mismatched prompt region rejected");rejectPrompt("フェーズ「P」の間だけ領域「R」を監視。好きに操作して","unsupported phase instruction rejected");System.out.println("TOTAL "+n+" phase checks passed; Android UI and gestures not tested.");}
}
